/* Lattice UI tokens
   CSS is the runtime source of truth. Primitive values are intentionally few;
   components consume semantic tokens so themes and density can change together. */

:root {
  /* Primitive palette */
  --lat-ink-950: #0b0c0e;
  --lat-ink-900: #131416;
  --lat-ink-850: #17191c;
  --lat-ink-800: #1c1e21;
  --lat-ink-750: #22252a;
  --lat-ink-700: #282b2f;
  --lat-ink-650: #2f3339;
  --lat-ink-600: #34383d;
  --lat-ink-500: #4a4f56;
  --lat-neutral-400: #737c87;
  --lat-neutral-300: #9aa1aa;
  --lat-neutral-200: #b7bcc2;
  --lat-neutral-100: #dee0e3;
  --lat-neutral-50: #f2f3f5;
  --lat-white: #ffffff;

  --lat-blue-700: #005fe0;
  --lat-blue-600: #006fff;
  --lat-blue-500: #2c82f2;
  --lat-blue-400: #4797ff;
  --lat-blue-300: #69aaff;
  --lat-blue-100: #eaf2ff;

  --lat-green-700: #16853a;
  --lat-green-500: #37be5f;
  --lat-green-300: #80d39a;
  --lat-amber-700: #9a6200;
  --lat-amber-500: #e6a23c;
  --lat-amber-300: #e7b75d;
  --lat-red-700: #c93038;
  --lat-red-500: #ff5c66;
  --lat-red-300: #ff9298;
  --lat-cyan-500: #63bde3;
  --lat-violet-500: #b47cde;

  /* Typography */
  --lat-font-sans: "Inter Variable", "PingFang SC", "Noto Sans SC", "Microsoft YaHei", sans-serif;
  --lat-font-data: "JetBrains Mono Variable", "SFMono-Regular", Consolas, monospace;
  --lat-text-2xs: 0.6875rem;
  --lat-text-xs: 0.75rem;
  --lat-text-sm: 0.8125rem;
  --lat-text-md: 0.875rem;
  --lat-text-lg: 1rem;
  --lat-text-xl: 1.25rem;
  --lat-text-2xl: 1.5rem;
  --lat-text-3xl: 2rem;
  --lat-leading-2xs: 1rem;
  --lat-leading-xs: 1rem;
  --lat-leading-sm: 1.125rem;
  --lat-leading-md: 1.25rem;
  --lat-leading-lg: 1.5rem;
  --lat-leading-xl: 1.75rem;
  --lat-leading-2xl: 2rem;
  --lat-leading-3xl: 2.5rem;

  /* Space */
  --lat-space-1: 2px;
  --lat-space-2: 4px;
  --lat-space-3: 6px;
  --lat-space-4: 8px;
  --lat-space-5: 10px;
  --lat-space-6: 12px;
  --lat-space-7: 16px;
  --lat-space-8: 20px;
  --lat-space-9: 24px;
  --lat-space-10: 32px;
  --lat-space-11: 40px;
  --lat-space-12: 48px;

  /* Shape */
  --lat-radius-xs: 3px;
  --lat-radius-sm: 4px;
  --lat-radius-md: 6px;
  --lat-radius-lg: 8px;
  --lat-radius-xl: 12px;
  --lat-radius-full: 9999px;
  --lat-border-width: 1px;

  /* Motion: state feedback only; no page-load choreography. */
  --lat-duration-fast: 120ms;
  --lat-duration-base: 180ms;
  --lat-duration-panel: 240ms;
  --lat-ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --lat-ease-in: cubic-bezier(0.4, 0, 1, 1);
  --lat-ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);

  /* Layers */
  --lat-z-sticky: 20;
  --lat-z-overlay: 40;
  --lat-z-dialog: 50;
  --lat-z-tooltip: 60;
}

/* Dark is the console's native environment. */
:root,
.dark {
  color-scheme: dark;
  --lat-canvas: var(--lat-ink-900);
  --lat-shell: var(--lat-ink-800);
  --lat-surface: var(--lat-ink-800);
  --lat-surface-raised: var(--lat-ink-750);
  --lat-surface-overlay: var(--lat-ink-700);
  --lat-surface-sunken: var(--lat-ink-950);
  --lat-line: rgb(249 250 250 / 0.08);
  --lat-line-strong: rgb(249 250 250 / 0.16);
  --lat-line-faint: rgb(249 250 250 / 0.045);
  --lat-text: var(--lat-neutral-100);
  --lat-text-muted: #a9b0b9;
  --lat-text-faint: #8f98a3;
  --lat-text-inverse: #0e1013;
  --lat-action: var(--lat-blue-400);
  --lat-action-hover: var(--lat-blue-300);
  --lat-action-pressed: var(--lat-blue-500);
  --lat-action-soft: rgb(71 151 255 / 0.13);
  --lat-action-text: #06182d;
  --lat-success: var(--lat-green-500);
  --lat-success-soft: rgb(55 190 95 / 0.13);
  --lat-warning: var(--lat-amber-500);
  --lat-warning-soft: rgb(230 162 60 / 0.13);
  --lat-danger: var(--lat-red-500);
  --lat-danger-soft: rgb(255 92 102 / 0.13);
  --lat-info: var(--lat-cyan-500);
  --lat-info-soft: rgb(99 189 227 / 0.13);
  --lat-series-1: var(--lat-cyan-500);
  --lat-series-2: var(--lat-violet-500);
  --lat-series-3: var(--lat-green-300);
  --lat-series-4: var(--lat-amber-300);
  --lat-grid: rgb(249 250 250 / 0.055);
  --lat-hover: rgb(249 250 250 / 0.045);
  --lat-selected: rgb(71 151 255 / 0.12);
  --lat-shadow-sm: 0 1px 2px rgb(0 0 0 / 0.25);
  --lat-shadow-panel: 0 10px 30px rgb(0 0 0 / 0.32);
  --lat-shadow-overlay: 0 24px 72px rgb(0 0 0 / 0.5);
  --lat-scrim: rgb(5 6 8 / 0.64);
}

.light {
  color-scheme: light;
  --lat-canvas: #f4f5f7;
  --lat-shell: var(--lat-white);
  --lat-surface: var(--lat-white);
  --lat-surface-raised: #f8f9fa;
  --lat-surface-overlay: var(--lat-white);
  --lat-surface-sunken: #eceef1;
  --lat-line: #e3e6ea;
  --lat-line-strong: #d2d7de;
  --lat-line-faint: #edf0f3;
  --lat-text: #181a1e;
  --lat-text-muted: #5c6470;
  --lat-text-faint: #66707b;
  --lat-text-inverse: var(--lat-white);
  --lat-action: #0063e6;
  --lat-action-hover: var(--lat-blue-700);
  --lat-action-pressed: #004db8;
  --lat-action-soft: #eaf2ff;
  --lat-action-text: var(--lat-white);
  --lat-success: var(--lat-green-700);
  --lat-success-soft: #e8f6ec;
  --lat-warning: var(--lat-amber-700);
  --lat-warning-soft: #fbf2df;
  --lat-danger: var(--lat-red-700);
  --lat-danger-soft: #fdecee;
  --lat-info: #146b8c;
  --lat-info-soft: #e7f5fa;
  --lat-series-1: #146b8c;
  --lat-series-2: #7a43a5;
  --lat-series-3: #16853a;
  --lat-series-4: #9a6200;
  --lat-grid: #e9ecf0;
  --lat-hover: #f3f5f7;
  --lat-selected: #eef5ff;
  --lat-shadow-sm: 0 1px 2px rgb(16 24 40 / 0.06);
  --lat-shadow-panel: 0 10px 30px rgb(16 24 40 / 0.08);
  --lat-shadow-overlay: 0 24px 72px rgb(16 24 40 / 0.16);
  --lat-scrim: rgb(15 20 28 / 0.34);
}

/* Compact is the default operating density. Roomy is for forms and reading. */
:root,
[data-density="compact"] {
  --lat-control-height: 30px;
  --lat-control-height-sm: 26px;
  --lat-row-height: 38px;
  --lat-section-pad: 16px;
  --lat-content-pad: 20px;
  --lat-rail-width: 56px;
  --lat-nav-width: 228px;
  --lat-topbar-height: 52px;
}

[data-density="roomy"] {
  --lat-control-height: 36px;
  --lat-control-height-sm: 30px;
  --lat-row-height: 46px;
  --lat-section-pad: 22px;
  --lat-content-pad: 28px;
}

@media (max-width: 900px) {
  :root {
    --lat-content-pad: 14px;
  }
}

@import "./tokens.css";

@custom-variant dark (&:where(.dark, .dark *));

@theme inline {
  --color-canvas: var(--lat-canvas);
  --color-shell: var(--lat-shell);
  --color-surface: var(--lat-surface);
  --color-raised: var(--lat-surface-raised);
  --color-overlay: var(--lat-surface-overlay);
  --color-sunken: var(--lat-surface-sunken);
  --color-line: var(--lat-line);
  --color-line-strong: var(--lat-line-strong);
  --color-line-faint: var(--lat-line-faint);
  --color-ink: var(--lat-text);
  --color-muted: var(--lat-text-muted);
  --color-faint: var(--lat-text-faint);
  --color-inverse: var(--lat-text-inverse);
  --color-action: var(--lat-action);
  --color-action-hover: var(--lat-action-hover);
  --color-action-soft: var(--lat-action-soft);
  --color-action-text: var(--lat-action-text);
  --color-success: var(--lat-success);
  --color-success-soft: var(--lat-success-soft);
  --color-warning: var(--lat-warning);
  --color-warning-soft: var(--lat-warning-soft);
  --color-danger: var(--lat-danger);
  --color-danger-soft: var(--lat-danger-soft);
  --color-info: var(--lat-info);
  --color-info-soft: var(--lat-info-soft);
  --color-series-1: var(--lat-series-1);
  --color-series-2: var(--lat-series-2);
  --color-series-3: var(--lat-series-3);
  --color-series-4: var(--lat-series-4);
  --color-hover: var(--lat-hover);
  --color-selected: var(--lat-selected);
  --font-sans: var(--lat-font-sans);
  --font-data: var(--lat-font-data);
  --radius-sm: var(--lat-radius-sm);
  --radius-md: var(--lat-radius-md);
  --radius-lg: var(--lat-radius-lg);
  --radius-xl: var(--lat-radius-xl);
}

@layer base {
  * {
    border-color: var(--lat-line);
  }

  html,
  body,
  #root {
    height: 100%;
  }

  html {
    background: var(--lat-canvas);
    font-synthesis: none;
    text-rendering: optimizeLegibility;
  }

  body {
    margin: 0;
    background: var(--lat-canvas);
    color: var(--lat-text);
    font-family: var(--lat-font-sans);
    font-size: var(--lat-text-md);
    line-height: var(--lat-leading-md);
    -webkit-font-smoothing: antialiased;
  }

  button,
  input,
  textarea,
  select {
    font: inherit;
  }

  button,
  [role="button"] {
    -webkit-tap-highlight-color: transparent;
  }

  ::selection {
    background: var(--lat-action);
    color: var(--lat-action-text);
  }

  :focus-visible {
    outline: 2px solid var(--lat-action);
    outline-offset: 2px;
  }

  input::placeholder,
  textarea::placeholder {
    color: var(--lat-text-faint);
    opacity: 1;
  }

  * {
    scrollbar-width: thin;
    scrollbar-color: var(--lat-line-strong) transparent;
  }

  *::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  *::-webkit-scrollbar-track {
    background: transparent;
  }

  *::-webkit-scrollbar-thumb {
    background: var(--lat-line-strong);
    border: 3px solid var(--lat-canvas);
    border-radius: 999px;
  }

  *::-webkit-scrollbar-thumb:hover {
    background: var(--lat-text-faint);
  }
}

@layer utilities {
  .lat-data {
    font-family: var(--lat-font-data);
    font-feature-settings: "tnum" 1, "zero" 1;
  }

  .lat-tabular {
    font-variant-numeric: tabular-nums;
  }

  .lat-hairline {
    box-shadow: inset 0 -1px 0 var(--lat-line);
  }

  .lat-focus-ring:focus-visible {
    outline: 2px solid var(--lat-action);
    outline-offset: 2px;
  }
}

@keyframes lat-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes lat-drawer-in {
  from { translate: 24px 0; }
  to { translate: 0 0; }
}

@keyframes lat-drawer-out {
  from { translate: 0 0; }
  to { translate: 24px 0; }
}

@keyframes lat-drawer-left-in {
  from { translate: -24px 0; }
  to { translate: 0 0; }
}

@keyframes lat-drawer-left-out {
  from { translate: 0 0; }
  to { translate: -24px 0; }
}

@keyframes lat-sheet-bottom-in {
  from { translate: 0 24px; }
  to { translate: 0 0; }
}

@keyframes lat-sheet-bottom-out {
  from { translate: 0 0; }
  to { translate: 0 24px; }
}

@keyframes lat-chart-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

@keyframes lat-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.45; }
}

@keyframes lat-indeterminate {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(300%); }
}

@keyframes lat-dialog-in {
  from { opacity: 0; translate: -50% -48%; scale: 0.985; }
  to { opacity: 1; translate: -50% -50%; scale: 1; }
}

@keyframes lat-dialog-out {
  from { opacity: 1; translate: -50% -50%; scale: 1; }
  to { opacity: 0; translate: -50% -48%; scale: 0.985; }
}

@keyframes lat-popover-in {
  from { opacity: 0; translate: 0 4px; }
  to { opacity: 1; translate: 0 0; }
}

@keyframes lat-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

@keyframes lat-toast-in {
  from { opacity: 0; translate: 12px 0; }
  to { opacity: 1; translate: 0 0; }
}

@keyframes lat-toast-out {
  from { opacity: 1; translate: 0 0; }
  to { opacity: 0; translate: 12px 0; }
}

@keyframes lat-link-flow {
  from { stroke-dashoffset: 24; }
  to { stroke-dashoffset: 0; }
}

.lat-overlay[data-state="open"] {
  animation: lat-fade-in var(--lat-duration-base) var(--lat-ease-out);
}

.lat-overlay[data-state="closed"] {
  animation: lat-fade-in var(--lat-duration-fast) var(--lat-ease-in) reverse;
}

.lat-popover-content {
  transform-origin: var(--radix-dropdown-menu-content-transform-origin, var(--radix-select-content-transform-origin, center));
}

.lat-popover-content[data-state="open"] {
  animation: lat-popover-in var(--lat-duration-fast) var(--lat-ease-out);
}

.lat-popover-content[data-state="closed"] {
  animation: lat-fade-in 90ms var(--lat-ease-in) reverse;
}

.lat-tooltip-content[data-state="delayed-open"],
.lat-tooltip-content[data-state="instant-open"] {
  animation: lat-fade-in var(--lat-duration-fast) var(--lat-ease-out);
}

.lat-dialog-content[data-state="open"] {
  animation: lat-dialog-in var(--lat-duration-base) var(--lat-ease-out);
}

.lat-dialog-content[data-state="closed"] {
  animation: lat-dialog-out var(--lat-duration-fast) var(--lat-ease-in);
}

.lat-sheet-content[data-state="open"] {
  animation: lat-drawer-in var(--lat-duration-panel) var(--lat-ease-out);
}

.lat-sheet-content[data-state="closed"] {
  animation: lat-drawer-out var(--lat-duration-base) var(--lat-ease-in);
}

.lat-sheet-content[data-side="left"][data-state="open"] {
  animation-name: lat-drawer-left-in;
}

.lat-sheet-content[data-side="left"][data-state="closed"] {
  animation-name: lat-drawer-left-out;
}

.lat-sheet-content[data-side="bottom"][data-state="open"] {
  animation-name: lat-sheet-bottom-in;
}

.lat-sheet-content[data-side="bottom"][data-state="closed"] {
  animation-name: lat-sheet-bottom-out;
}

.lat-skeleton {
  background-image: linear-gradient(
    100deg,
    var(--lat-surface-raised) 30%,
    var(--lat-hover) 50%,
    var(--lat-surface-raised) 70%
  );
  background-size: 200% 100%;
  animation: lat-shimmer 1.8s linear infinite;
}

.lat-dialog-content {
  translate: -50% -50%;
}

.lat-toast {
  animation: lat-toast-in 180ms var(--lat-ease-out);
}

.lat-topology-link {
  animation: lat-link-flow 1.4s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
